import sys, json, os, traceback, time
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
import numpy as np
from PIL import Image
r=Robot()
os.makedirs('/app/output/obs',exist_ok=True)
json.dump(r.spec(),open('/app/output/spec.json','w'),indent=2)
i=0
last=None
def save(res):
 global i,last
 last=res
 d=f'/app/output/obs/{i:03d}'
 res.save(d)
 print(json.dumps({'dir':d,'meta':res.meta}),flush=True)
 i+=1
save(r.get_obs(depth=True))
for line in sys.stdin:
 try:
  c=json.loads(line)
  op=c.pop('op')
  if op=='obs': save(r.get_obs(**c))
  elif op=='submit': save(r.submit(**c))
  elif op=='status': print(json.dumps(r.status()),flush=True)
  elif op=='ik': print(json.dumps(r.ik(**c)),flush=True)
  elif op=='fk': print(json.dumps(r.fk(**c)),flush=True)
  elif op=='pixels':
   cam=c['cam']; K=np.array(last.meta['cameras'][cam]['intrinsic_cv']); E=np.array(last.meta['cameras'][cam]['extrinsic_cv']); out=[]
   for u,v in c['pixels']:
    z=float(last.last_depth[cam][v,u]); pc=np.linalg.inv(K)@np.array([u,v,1])*z; pw=E[:,:3].T@(pc-E[:,3]); out.append({'uv':[u,v],'z':z,'world':pw.tolist()})
   print(json.dumps(out),flush=True)
 except Exception as e:
  traceback.print_exc()
  if 'Connection' in str(type(e)) or '500' in str(e) or '502' in str(e):
   print('RECOVERY',r.wait_ready(),flush=True)
PY
